    val KeepScreenOn: ImageVector by lazy { iconOf("ReaderKeepScreenOn", KEEP_SCREEN_ON_PATH) }
    val AutoScroll: ImageVector by lazy { iconOf("ReaderAutoScroll", AUTO_SCROLL_PATH) }
    val Palette: ImageVector by lazy { iconOf("ReaderPalette", PALETTE_PATH) }
    val Ai: ImageVector by lazy { iconOf("ReaderAi", AI_PATH) }
    val Close: ImageVector by lazy { iconOf("ReaderClose", CLOSE_PATH) }

    /** Auto-mirrored like the drawable it replaces (`android:autoMirrored="true"`): the speaker has
     * to face the sound in an RTL layout. */
    val VolumeUp: ImageVector by lazy { iconOf("ReaderVolumeUp", VOLUME_UP_PATH, autoMirror = true) }

    private fun iconOf(
        name: String,
        pathData: String,
        autoMirror: Boolean = false,
        /** 24 for the older Material Icons grid (`apps`, `handyman`), 960 for Symbols. */
        viewport: Float = 960f,
    ) = ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = viewport,
            viewportHeight = viewport,
            autoMirror = autoMirror
        ).apply {
            // Android benchmark parity: use the same PathParser + addPath pattern
            // as the working Material icons (FilledIcons.materialIcon). The previous
            // path() + addPathNodes() variant rendered nothing on iOS while the
            // Material Menu/Search icons (PathParser) stayed visible, leaving only
            // hamburger + search visible in the bottom toolbar.
            addPath(
                pathData = PathParser().parsePathString(pathData).toNodes(),
                fill = SolidColor(Color.Black)
            )
        }.build()
}
